-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

-- File choosers should open as centered dialogs, even without parent metadata.
-- Match complete dialog titles so normal browser and file-manager windows tile.
hl.window_rule({
    name = "floating-file-choosers",
    match = {
        title = "(?i)^(save as|save file|save file as|save image|save image as|save document|open file|open files|open folder|select file|select files|select folder|select a file|select a folder|choose file|choose files|choose folder|choose a file|choose a folder)([.]{3}|…)?$",
    },
    float = true,
    size = { 850, 500 },
    center = true,
})

-- GTK portal file choosers can use an application-provided dialog title.
hl.window_rule({
    name = "floating-portal-file-choosers",
    match = { class = "^(xdg-desktop-portal-gtk|org[.]gtk[.]FileChooser)$" },
    float = true,
    size = { 850, 500 },
    center = true,
})

hl.window_rule({
    name = "floating-thunar-file-progress",
    match = {
        class = "(?i)^thunar$",
        title = "^File Operation Progress$",
    },
    float = true,
    size = { 560, 180 },
    center = true,
})

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

